// Where a finished off-day post goes and when, as Growth already knows it (Krish, 2026-11-19: "I've never decided the
// channels before. They are just known by the growth repository. Post time, I've never decided before. Caption always
// gets generated by the growth repository.").
//
// The channels and the four daily slots are growth-makeyourmindup's mix.json, vendored byte for byte
// (vendor/makeyourmindup/mix.json, pinned by sha256 in tests/control-plane/growth-placement.test.ts, the same way
// subscribe-route.json is). This file only maps a board kind to one of Growth's lanes; it holds no channel or time of
// its own. The Publish prompt carries the answer so a session never asks him, and never stops for want of one.
import mix from '../../../../vendor/makeyourmindup/mix.json' with { type: 'json' }

export type PlacementKind = 'supporting' | 'voiceover' | 'explainer' | 'good_news' | 'meme'

interface Lane { placements: Record<string, string> }
const LANES = (mix as unknown as { lanes: Record<string, Lane> }).lanes
const CHANNELS = (mix as unknown as { channels: string[] }).channels
const TIMES = (mix as unknown as { slot_times: string[] }).slot_times

/** The Growth lane each board kind belongs to. A voiceover short takes the video lane (the publication's short-video
 *  placements): the four channels with their video formats. */
const LANE_OF: Record<PlacementKind, string> = {
  meme: 'meme',
  explainer: 'repurposed_carousel',
  supporting: 'repurposed_carousel',
  good_news: 'positive_news',
  voiceover: 'positive_news',
}
export const CHANNEL_NAME: Record<string, string> = { instagram: 'Instagram', tiktok: 'TikTok', youtube: 'YouTube', x: 'X' }

export interface Placement { lane: string; channels: Array<{ channel: string; name: string; format: string }>; times: string[] }

/** Growth's channels and formats for a board kind, in Growth's own channel order, and its four daily slot times (New York). */
export function placementFor(kind: string): Placement | null {
  const lane = LANE_OF[kind as PlacementKind]
  const p = lane ? LANES[lane]?.placements : null
  if (!p) return null
  return { lane, channels: CHANNELS.filter(c => p[c]).map(c => ({ channel: c, name: CHANNEL_NAME[c] ?? c, format: p[c] })), times: [...TIMES] }
}

/** "Instagram, TikTok, YouTube and X" */
export function channelWords(p: Placement): string {
  const n = p.channels.map(c => c.name)
  return n.length > 1 ? `${n.slice(0, -1).join(', ')} and ${n[n.length - 1]}` : n[0] ?? ''
}

/** The file id inside a Drive link, or null. */
export function driveId(url: string): string | null {
  const m = /\/d\/([A-Za-z0-9_-]{10,})|[?&]id=([A-Za-z0-9_-]{10,})/.exec(url)
  return m ? m[1] ?? m[2] ?? null : null
}

/** The address Buffer fetches a Drive file from. Drive's share page is for people; this form returns the bytes, and is how
 *  Buffer took the 18 Nov explainer's eight images. */
export function bufferUrl(url: string): string {
  const id = driveId(url)
  return id ? `https://drive.google.com/uc?export=download&id=${id}` : url
}
